function smart(q){q=" "+String(q).toLowerCase()+" ";const out=[],seen=new Set();SMART.forEach(([re,c,s])=>{if(re.test(q)&&!seen.has(c+s)){seen.add(c+s);out.push({label:s,cat:c,sub:s,smart:1})}});return out.slice(0,4)}
