  const u={id:"c"+uid(),role:"contractor",name:o.name.trim(),email:o.email.trim(),phone:o.phone||"",biz:o.biz.trim(),trade:o.trade,subs:o.subs&&o.subs.length?o.subs:[CATS[o.trade][0]],zip:o.zip,radius:+o.radius||40,rate:o.rate||"Quote per job",verified:!!(o.license&&o.insurance),license:o.license||"",insurance:o.insurance||"",years:+o.years||1,avail:o.avail&&o.avail.length?o.avail:["Weekdays"],availNow:!!o.availNow,bg:false,founding:true,resp:3,bio:o.bio||"",paid:true,plan:o.plan||"founding",favs:[],portfolio:(o.portfolio||[]).map(t=>({id:uid(),title:t,cap:"Portfolio"})),joined:Date.now()};
