Object.assign(A,{
 signupPM(o){if(!String(o.name||"").trim()||!String(o.biz||"").trim()||!/^\S+@\S+\.\S+$/.test(o.email||""))return{ok:false,msg:"Enter your name, company and a valid email."};const u={id:"m"+uid(),role:"pm",name:o.name.trim(),biz:o.biz.trim(),email:o.email.trim(),zip:ZIPS[o.zip]?o.zip:"78704",favs:[],bio:"",joined:Date.now(),plan:"founding"};DB.users.push(u);DB.me=u.id;notify(u.id,"Welcome! Post your first project and list the crew you need.","newproject");save();return{ok:true,msg:"Welcome, "+u.name.split(" ")[0]+"! Your 3 free months have started."}},
 postProject(o){const m=me();if(!canPostProject(m))return{ok:false,need:"login",msg:"Sign in as a project manager or contractor to post a project"};if(!String(o.title||"").trim())return{ok:false,msg:"Give the project a title."};const roles=(o.roles||[]).filter(r=>r.trade&&+r.need>0);if(!roles.length)return{ok:false,msg:"Add at least one crew role."};
  const p={id:"p"+uid(),pm:m.id,type:o.type||"custom",title:o.title.trim(),zip:ZIPS[o.zip]?o.zip:m.zip,budget:o.budget||"Open",start:o.start||"",end:o.end||"",desc:o.desc||"",status:"open",phase:0,created:Date.now(),phases:(o.phases&&o.phases.length?o.phases:PTPL[o.type||"custom"].phases).slice(),roles:roles.map((r,i)=>({id:"r"+(i+1),trade:r.trade,label:String(r.label||r.trade).trim()||r.trade,need:Math.min(20,+r.need),filled:[],done:[],apps:[]}))};
  DB.projects.push(p);const tr=new Set(p.roles.map(r=>r.trade));PROS().filter(u=>tr.has(u.trade)&&dist(u.zip,p.zip)<=u.radius).forEach(u=>notify(u.id,`New crew opening near you: ${p.title}`,"project:"+p.id));save();return{ok:true,msg:"Project posted. Matching pros were notified.",id:p.id}},
 applyRole(pid,rid,note){const m=me(),p=PJ(pid);if(!m||m.role!=="contractor")return{ok:false,need:"login",msg:"Sign in as a pro to apply"};const r=p.roles.find(x=>x.id===rid);if(p.pm===m.id)return{ok:false,msg:"That's your own project"};if(r.filled.includes(m.id))return{ok:false,msg:"You're already on this crew"};if(r.filled.length>=r.need)return{ok:false,msg:"That role is full"};if(r.apps.some(a=>a.cid===m.id&&a.status==="pending"))return{ok:false,msg:"You already applied"};
  r.apps.push({cid:m.id,note:String(note||"").trim(),date:Date.now(),status:"pending"});notify(p.pm,`${m.biz} applied: ${r.label} (${p.title})`,"project:"+pid);save();return{ok:true,msg:"Applied. The project manager will review it."}},
 acceptApp(pid,rid,cid){const m=me(),p=PJ(pid);if(!m||p.pm!==m.id)return{ok:false,msg:"Only the project manager can accept"};const r=p.roles.find(x=>x.id===rid);if(r.filled.length>=r.need)return{ok:false,msg:"All slots for this role are filled"};const a=r.apps.find(x=>x.cid===cid&&x.status==="pending");if(!a)return{ok:false,msg:"Application not found"};a.status="accepted";r.filled.push(cid);if(r.filled.length>=r.need)r.apps.forEach(x=>{if(x.status==="pending")x.status="waitlist"});if(p.status==="open"&&slots(p).open===0)p.status="active";notify(cid,`You're on the crew: ${r.label}, ${p.title}`,"project:"+pid);save();return{ok:true,msg:`${U(cid).biz} added to the crew`}},
 declineApp(pid,rid,cid){const m=me(),p=PJ(pid);if(!m||p.pm!==m.id)return{ok:false,msg:"Only the project manager can decline"};const a=p.roles.find(x=>x.id===rid).apps.find(x=>x.cid===cid&&x.status!=="accepted");if(a)a.status="declined";notify(cid,`Your application for ${p.title} wasn't selected this time.`,"projects");save();return{ok:true,msg:"Application declined"}},
 markDone(pid,rid,cid){const m=me(),p=PJ(pid);if(!m||p.pm!==m.id)return{ok:false,msg:"Only the project manager can do that"};const r=p.roles.find(x=>x.id===rid);if(!r.filled.includes(cid))return{ok:false,msg:"Not on this crew"};if(!r.done.includes(cid))r.done.push(cid);notify(cid,`Your part on ${p.title} was marked complete.`,"project:"+pid);save();return{ok:true,msg:"Part marked complete. Crew review unlocked."}},
 canReviewCrew(pid,rid,cid){const m=me(),p=PJ(pid);const r=p&&p.roles.find(x=>x.id===rid);return!!(m&&p&&p.pm===m.id&&r&&r.done.includes(cid)&&!DB.reviews.some(x=>x.proj===pid&&x.role===rid&&x.cid===cid))},
 reviewCrew(pid,rid,cid,sub,text){if(!A.canReviewCrew(pid,rid,cid))return{ok:false,msg:"Crew reviews unlock after their part is marked complete."};const vals=SUBS.map(k=>+sub[k]||0);if(vals.some(v=>v<1))return{ok:false,msg:"Rate all four categories."};if(String(text||"").trim().length<10)return{ok:false,msg:"Write at least a sentence (10+ characters)."};const stars=Math.round(vals.reduce((a,b)=>a+b)/4);
  DB.reviews.push({id:uid(),cid,uid:me().id,job:null,proj:pid,role:rid,stars,sub:Object.fromEntries(SUBS.map((k,i)=>[k,vals[i]])),text:text.trim(),date:Date.now(),reply:""});notify(cid,`New ${stars}★ crew review from ${nameOf(me())}`,"profile:"+cid);save();return{ok:true,msg:"Crew review posted"}},
 advancePhase(pid){const m=me(),p=PJ(pid);if(!m||p.pm!==m.id)return{ok:false,msg:"Only the project manager can do that"};if(p.phase<p.phases.length-1){p.phase++;p.status="active";crewOf(p).forEach(c=>notify(c,`${p.title}: now in "${p.phases[p.phase]}"`,"project:"+pid));save();return{ok:true,msg:"Moved to: "+p.phases[p.phase]}}p.status="completed";p.phase=p.phases.length;save();return{ok:true,msg:"Project complete. Nice work!"}},
 crewSend(pid,to,text){const m=me(),p=PJ(pid);if(!m||!(p.pm===m.id||crewOf(p).includes(m.id)))return{ok:false,msg:"Only the PM and crew can message here"};if(!String(text||"").trim())return{ok:false,msg:"Type a message"};to=to||"all";DB.pmsgs.push({id:uid(),pid,from:m.id,to,text:text.trim(),date:Date.now()});(to==="all"?[p.pm,...crewOf(p)]:[to]).filter(x=>x!==m.id).forEach(x=>notify(x,`${nameOf(m)} · ${p.title}: ${text.trim().slice(0,60)}`,"project:"+pid));save();
  if(m.id===p.pm){const rep=to==="all"?crewOf(p)[0]:to;if(rep&&DB.pmsgs.filter(x=>x.from===rep).length<40)setTimeout(()=>{DB.pmsgs.push({id:uid(),pid,from:rep,to:to==="all"?"all":p.pm,text:"Got it, thanks. We'll be there. (auto-reply, demo)",date:Date.now()});save();if(window.onData)window.onData()},1400)}return{ok:true}}});
{const lt=linkTo;linkTo=function(l){const[a,b]=String(l||"").split(":");if(a==="project")return go("project",b);if(a==="newproject"||a==="projects")return go(a);return lt(l)}}
Object.assign(TITLES,{projects:"Projects",project:"Project",newproject:"Post a project"});
FAQS.push(["What are projects?","A project is a multi-trade job, like a pool build or a pole barn. A project manager or general contractor lists the crew they need (for example 2 excavators, 1 electrician, 3 concrete finishers), and pros apply for a specific slot. No full-time staff needed."],["What does it cost to post a project?","Project managers and GCs use the same $20/mo pro plan, with no per-project or per-hire fees. Founding members get 3 months free. Applying to crew slots is included in every pro plan."]);
