const slotDots=r=>`<span class="slots" role="img" aria-label="${r.filled.length} of ${r.need} filled">${Array.from({length:r.need},(_,i)=>{const c=r.filled[i];return c?`<span class="slot on" title="${esc(nameOf(U(c)))}" style="--h:${hash(c)%360}">${ini(nameOf(U(c)))}</span>`:`<span class="slot"></span>`}).join("")}</span>`;
function projCard(p){const s=slots(p),pm=U(p.pm),pct=Math.round(s.f/s.n*100);return`<article class="projcard"><div class="pj-art">${projArt(p.type,p.title)}<span class="pj-type">${I(PTPL[p.type]?PTPL[p.type].icon:"layers",14)}${esc((PTPL[p.type]||PTPL.custom).t)}</span>${p.status==="completed"?`<span class="pj-st done">Complete</span>`:s.open?`<span class="pj-st">${s.open} open slot${s.open===1?"":"s"}</span>`:`<span class="pj-st full">Crew full</span>`}</div><div class="pj-b"><h3><a href="${href("project",p.id)}" class="pj-link">${esc(p.title)}</a></h3><p class="muted small pj-meta"><span>${I("pin",13)}${esc(townOf(p.zip))}</span><span>${I("clock",13)}${fmtD(p.start)}–${fmtD(p.end)}</span><span>${esc(p.budget)}</span></p><ul class="needs">${p.roles.map(r=>`<li class="${r.filled.length>=r.need?"full":""}"><span>${esc(r.trade)}</span><b>${r.filled.length}/${r.need}</b></li>`).join("")}</ul><div class="pj-foot"><div class="meter" role="progressbar" aria-label="Crew filled" aria-valuenow="${pct}" aria-valuemin="0" aria-valuemax="100"><i style="width:${pct}%"></i></div><span class="small muted">${s.f}/${s.n} crew · by ${esc(nameOf(pm))}</span></div></div></article>`}
function phaseLine(p){return`<ol class="phases" aria-label="Project phases">${p.phases.map((ph,i)=>`<li class="${i<p.phase?"done":i===p.phase?"now":""}"><span class="pdot">${i<p.phase?I("check",13):i+1}</span><span class="pl">${esc(ph)}</span>${i===p.phase?`<span class="sr"> (current phase)</span>`:""}</li>`).join("")}</ol>`}
let PJTAB={};
VIEWS.projects=(x,q)=>{const m=me();const tr=q.trade||"",open=q.open==="1";let ps=(DB.projects||[]).filter(p=>(!tr||p.roles.some(r=>r.trade===tr))&&(!open||slots(p).open>0)).sort((a,b)=>b.created-a.created);const trades=[...new Set(DB.projects.flatMap(p=>p.roles.map(r=>r.trade)))].sort();
 return`<section class="page projpage"><div class="projhero"><div><span class="kick">${I("users",16)} Projects · multi-trade crews</span><h1>Big job? Post the project, list the crew.</h1><p class="lede">Pool builds, pole barns, remodels. Say who you need (2 excavators, 1 electrician, 3 concrete finishers) and local pros apply for the exact slot. No full-time staff, no lead fees.</p><div class="row wrapr"><a class="btn primary" href="${href("newproject")}">${I("plus",16)}Post a project</a>${m&&m.role==="contractor"?`<a class="btn" href="${href("projects",null,{trade:m.trade,open:"1"})}">${I("search",16)}Openings for ${esc(m.trade)}</a>`:`<a class="btn" href="${href("pricing")}">PMs: same $20/mo plan</a>`}</div></div><div class="crewviz" aria-hidden="true">${crewViz()}</div></div>
 <form id="pjf" class="pjfilter row wrapr" aria-label="Filter projects"><div class="fld"><label for="pj-trade">Trade needed</label><select id="pj-trade" name="trade"><option value="">All trades</option>${trades.map(t=>`<option ${t===tr?"selected":""}>${esc(t)}</option>`).join("")}</select></div><label class="chk"><input type="checkbox" name="open" ${open?"checked":""}> Only with open slots</label><p class="muted small" aria-live="polite">${ps.length} project${ps.length===1?"":"s"}</p></form>
 <div class="projgrid">${ps.map(projCard).join("")||empty("users","No projects match","Try another trade.","")}</div></section>`};
