function applyModal(pid,rid){const m=me(),p=PJ(pid),r=p.roles.find(x=>x.id===rid);if(!m){go("signup",null,{next:"/project/"+pid});toast("Sign in as a pro to apply","err");return}if(m.role!=="contractor"){toast(m.role==="pm"?"Project managers can't apply to crews. Switch to a pro account.":"Only pros can apply to crew slots","err");return}
 modal(`<h2 id="mtitle">Apply: ${esc(r.label)}</h2><p class="muted">${esc(p.title)} · ${esc(townOf(p.zip))} · ${r.need-r.filled.length} of ${r.need} slot(s) open</p>${m.trade!==r.trade?`<p class="badge b-fast">${I("info",12)}This role is for ${esc(r.trade)}. Your trade is ${esc(m.trade)}.</p>`:""}<form id="apf" class="form"><div class="fld"><label for="apNote">Note to the project manager</label><textarea id="apNote" name="note" rows="3" placeholder="Crew size, availability, similar projects…"></textarea></div><div class="actions"><button type="button" class="btn ghost" data-close>Cancel</button><button class="btn primary">${I("send",16)}Send application</button></div></form>`);
 document.querySelectorAll("#modal [data-close]").forEach(x=>x.onclick=closeModal);document.getElementById("apf").onsubmit=e=>{e.preventDefault();const r2=A.applyRole(pid,rid,readForm(e.target).note);if(r2.ok){closeModal();act(r2,render)}else act(r2)}}
function crewReviewModal(pid,rid,cid){const p=PJ(pid),r=p.roles.find(x=>x.id===rid),u=U(cid);modal(`<h2 id="mtitle">Review ${esc(u.biz)}</h2><p class="muted">${esc(r.label)} on “${esc(p.title)}”. Shows as a <b>Verified crew review</b>.</p><form id="revf" class="form">${SUBS.map(k=>starInput("rv_"+k,k[0].toUpperCase()+k.slice(1))).join("")}<div class="fld"><label for="rvt">Your review</label><textarea id="rvt" name="text" rows="4" placeholder="Quality, reliability, how they worked with the rest of the crew…"></textarea></div><div class="actions"><button type="button" class="btn ghost" data-close>Later</button><button class="btn primary">Post review</button></div></form>`);
 document.querySelectorAll("#modal [data-close]").forEach(x=>x.onclick=closeModal);document.getElementById("revf").onsubmit=e=>{e.preventDefault();const f=readForm(e.target);const sub={};SUBS.forEach(k=>sub[k]=f["rv_"+k]);const res=A.reviewCrew(pid,rid,cid,sub,f.text);if(res.ok){closeModal();act(res,render)}else act(res)}}
/* --- post-project wizard --- */
let NP=null;const NPS=["Project","Where & when","Crew","Review"];
function npNew(t){t=t||"pool";const T=PTPL[t];NP={step:0,type:t,title:t==="custom"?"":T.t,zip:(me()&&me().zip)||"78704",start:"",end:"",budget:"",desc:"",roles:T.roles.map(([trade,label,need])=>({trade,label,need})),phases:T.phases.slice()}}
VIEWS.newproject=()=>{const m=me();if(!canPostProject(m))return`<section class="page narrow">${empty("users","Post a project","Project managers and contractors can post multi-trade projects and pick a crew slot by slot.",`<a class="btn primary" href="${href("signup",null,{next:"/newproject"})}">Sign in or join as a PM</a>`)}</section>`;
 if(!NP)npNew();const s=NP.step;const sl=NP.roles.reduce((a,r)=>a+(+r.need||0),0);
 const step=s===0?`<fieldset><legend class="h-sub">What are you building?</legend><div class="tplgrid">${Object.entries(PTPL).map(([k,T])=>`<label class="tpl ${NP.type===k?"on":""}"><input type="radio" name="type" value="${k}" data-tpl="${k}" ${NP.type===k?"checked":""}><span class="tpl-i">${I(T.icon,26)}</span><b>${T.t}</b><small>${k==="custom"?"Start from scratch":T.roles.reduce((a,r)=>a+r[2],0)+" crew · "+T.roles.length+" trades"}</small></label>`).join("")}</div></fieldset><div class="fld"><label for="np-title">Project title</label><input id="np-title" name="title" value="${esc(NP.title)}" placeholder="e.g. Inground pool build, Glen Arbor"></div><div class="fld"><label for="np-desc">Details</label><textarea id="np-desc" name="desc" rows="4" placeholder="Size, materials, site conditions, what's already done…">${esc(NP.desc)}</textarea></div>`
 :s===1?`<div class="two"><div class="fld"><label for="np-zip">Location</label><select id="np-zip" name="zip">${zipOpts(NP.zip)}</select></div><div class="fld"><label for="np-budget">Budget</label><input id="np-budget" name="budget" value="${esc(NP.budget)}" placeholder="$85,000–110,000"></div><div class="fld"><label for="np-start">Start date</label><input id="np-start" type="date" name="start" value="${esc(NP.start)}"></div><div class="fld"><label for="np-end">Target finish</label><input id="np-end" type="date" name="end" value="${esc(NP.end)}"></div></div><div class="fld"><label for="np-phases">Phases (one per line)</label><textarea id="np-phases" name="phases" rows="5">${esc(NP.phases.join("\n"))}</textarea></div>`
 :s===2?`<p class="muted">List every role and how many people you need. Pros apply for a specific slot.</p><div class="nproles">${NP.roles.map((r,i)=>`<div class="np-row card"><div class="fld"><label for="npt${i}">Trade</label><select id="npt${i}" name="trade${i}" class="np-trade">${tradeOpts(r.trade)}</select></div><div class="fld grow"><label for="npl${i}">Role</label><input id="npl${i}" name="label${i}" value="${esc(r.label)}" placeholder="e.g. Concrete finishers"></div><div class="fld qty"><span class="lbl" id="nqlbl${i}">Needed</span><div class="stepper" role="group" aria-labelledby="nqlbl${i}"><button type="button" data-q="${i}:-1" aria-label="Fewer">−</button><input id="npq${i}" name="need${i}" inputmode="numeric" value="${r.need}" aria-label="Number needed for role ${i+1}"><button type="button" data-q="${i}:1" aria-label="More">+</button></div></div><button type="button" class="iconbtn" data-rm="${i}" aria-label="Remove role ${i+1}">${I("x",18)}</button></div>`).join("")}</div><button type="button" class="btn" id="npAdd">${I("plus",16)}Add a role</button><p class="crewsum">${I("users",16)} <b>${sl}</b> people across <b>${NP.roles.length}</b> trades</p>`
 :`<div class="npreview card"><span class="kick">${esc(PTPL[NP.type].t)}</span><h2>${esc(NP.title||"Untitled project")}</h2><p class="muted">${esc(townOf(NP.zip))} · ${fmtD(NP.start)} – ${fmtD(NP.end)} · ${esc(NP.budget||"Budget open")}</p><p>${esc(NP.desc)}</p><ul class="needs">${NP.roles.map(r=>`<li><span>${esc(r.label||r.trade)}</span><b>×${r.need}</b></li>`).join("")}</ul><ol class="phases mini">${NP.phases.map((ph,i)=>`<li><span class="pdot">${i+1}</span><span class="pl">${esc(ph)}</span></li>`).join("")}</ol></div><p class="muted small">${I("shield",14)} Free for project managers. No per-project or per-hire fees.</p>`;
 return`<section class="page narrow npwiz"><div class="pagehead"><span class="kick">${I("users",14)} Post a project</span><h1>${["What's the project?","Where and when?","Who do you need?","Look good?"][s]}</h1></div><ol class="wsteps" aria-label="Steps">${NPS.map((t,i)=>`<li class="${i<s?"done":i===s?"cur":""}" ${i===s?'aria-current="step"':""}><span>${i<s?I("check",12):i+1}</span>${t}</li>`).join("")}</ol><form id="npf" class="form card" novalidate>${step}<p id="nperr" class="err" role="alert"></p><div class="actions">${s?`<button type="button" class="btn ghost" id="npBack">${I("back",16)}Back</button>`:`<span></span>`}${s<3?`<button class="btn primary" id="npNext">Continue ${I("chev",16)}</button>`:`<button class="btn primary" id="npPost">${I("check",16)}Post project</button>`}</div></form></section>`};
AFTER.newproject=()=>{const f=document.getElementById("npf");if(!f)return;const grab=()=>{const o=readForm(f);["title","desc","zip","budget","start","end"].forEach(k=>{if(k in o)NP[k]=o[k]});if("phases" in o)NP.phases=o.phases.split("\n").map(x=>x.trim()).filter(Boolean);if(NP.step===2)NP.roles=NP.roles.map((r,i)=>({trade:o["trade"+i],label:o["label"+i],need:Math.max(1,Math.min(20,parseInt(o["need"+i])||1))}))};const err=t=>{document.getElementById("nperr").textContent=t};
 f.querySelectorAll("[data-tpl]").forEach(x=>x.onchange=()=>{const t=x.dataset.tpl;grab();const keep={desc:NP.desc,zip:NP.zip};npNew(t);Object.assign(NP,keep);render()});
 f.querySelectorAll("[data-q]").forEach(x=>x.onclick=()=>{const[i,d]=x.dataset.q.split(":").map(Number);grab();NP.roles[i].need=Math.max(1,Math.min(20,NP.roles[i].need+d));render();document.querySelector(`[data-q="${i}:${d}"]`).focus()});
 f.querySelectorAll("[data-rm]").forEach(x=>x.onclick=()=>{grab();if(NP.roles.length<2)return err("Keep at least one role.");NP.roles.splice(+x.dataset.rm,1);render()});
 const ad=document.getElementById("npAdd");ad&&(ad.onclick=()=>{grab();NP.roles.push({trade:"",label:"",need:1});render();const l=document.querySelectorAll(".np-trade");l[l.length-1].focus()});
 const bk=document.getElementById("npBack");bk&&(bk.onclick=()=>{grab();NP.step--;render()});
 f.onsubmit=e=>{e.preventDefault();grab();if(NP.step===0&&!NP.title.trim())return err("Give your project a title.");if(NP.step===1&&NP.start&&NP.end&&NP.end<NP.start)return err("Finish date is before the start date.");if(NP.step===2){if(NP.roles.some(r=>!r.trade))return err("Pick a trade for every role.")}
  if(NP.step<3){NP.step++;render();return}const r=A.postProject(NP);if(r.ok){NP=null;act(r,()=>go("project",r.id))}else act(r)}};
/* --- dashboards & signup --- */
function pmDash(m){const ps=DB.projects.filter(p=>p.pm===m.id).sort((a,b)=>b.created-a.created);const open=ps.reduce((a,p)=>a+slots(p).open,0),apps=ps.reduce((a,p)=>a+pendingApps(p),0),crew=new Set(ps.flatMap(crewOf)).size;const toRev=ps.flatMap(p=>p.roles.flatMap(r=>r.done.filter(c=>A.canReviewCrew(p.id,r.id,c)).map(c=>({p,r,c}))));
 return`<section class="page dash pmdash"><div class="pagehead row sb wrapr"><div><span class="kick">${I("users",14)} Project manager</span><h1>${esc(nameOf(m))}</h1><p class="muted">${esc(m.name)} · ${esc(townOf(m.zip))}</p></div><a class="btn primary" href="${href("newproject")}">${I("plus",16)}Post a project</a></div>
 <div class="kpis">${[[ps.length,"projects"],[crew,"crew members"],[open,"open slots"],[apps,"applicants waiting"]].map(([n,t])=>`<div class="kpi card"><b>${n}</b><span>${t}</span></div>`).join("")}</div>
 ${toRev.length?`<div class="card nudge">${I("star",20)}<div><b>${toRev.length} crew review${toRev.length>1?"s":""} waiting</b><p class="muted small">${toRev.map(x=>esc(U(x.c).biz)).join(", ")}</p></div><a class="btn sm" href="${href("project",toRev[0].p.id,{tab:"crew"})}">Review now</a></div>`:""}
 <h2 class="h-sub">Your projects</h2><div class="pmlist">${ps.map(p=>{const s=slots(p),pa=pendingApps(p);return`<a class="pmrow card" href="${href("project",p.id)}"><div class="pm-t"><b>${esc(p.title)}</b><span class="muted small">${esc(townOf(p.zip))} · ${p.status==="completed"?"Complete":esc(p.phases[Math.min(p.phase,p.phases.length-1)])}</span></div><div class="meter" aria-hidden="true"><i style="width:${Math.round(s.f/s.n*100)}%"></i></div><span class="small"><b>${s.f}/${s.n}</b> crew</span>${pa?`<span class="badge b-fast">${pa} new</span>`:""}${I("chev",16)}</a>`}).join("")||empty("users","No projects yet","Post a pool build, pole barn or remodel and list the crew you need.",`<a class="btn primary" href="${href("newproject")}">Post a project</a>`)}</div>
 <h2 class="h-sub">Notifications</h2>${notifList(m,6)}</section>`}
{const ov=VIEWS.dash;VIEWS.dash=()=>{const m=me();if(m&&m.role==="pm")return pmDash(m);let h=ov();if(m&&m.role==="contractor"){const mp=myProjects();const blk=`<section class="projmine"><div class="row sb"><h2 class="h-sub">${I("users",18)} Project crews</h2><a href="${href("projects",null,{trade:m.trade,open:"1"})}">Find openings</a></div>${mp.length?`<div class="pmlist">${mp.map(p=>{const r=p.roles.find(x=>x.filled.includes(m.id)||x.apps.some(a=>a.cid===m.id));const st=r.filled.includes(m.id)?(r.done.includes(m.id)?"Part complete":"On the crew"):(r.apps.find(a=>a.cid===m.id)||{}).status;return`<a class="pmrow card" href="${href("project",p.id)}"><div class="pm-t"><b>${esc(p.title)}</b><span class="muted small">${esc(r.label)} · ${esc(townOf(p.zip))}</span></div><span class="badge">${esc(st==="pending"?"Applied":st==="waitlist"?"Waitlist":st==="declined"?"Not selected":st)}</span>${I("chev",16)}</a>`}).join("")}</div>`:`<p class="muted">Apply for a slot on a multi-trade project. ${DB.projects.filter(p=>p.roles.some(r=>r.trade===m.trade&&r.filled.length<r.need)).length} open for ${esc(m.trade)} right now.</p>`}</section>`;h=h.replace(/<\/section>\s*$/,blk+"</section>")}return h}}
{const ov=VIEWS.signup;VIEWS.signup=(p,q)=>{let h=ov(p,q);const card=`<form class="card form pm-side" id="pmsf"><h2>${I("users",20)} I manage projects</h2><p class="muted small">PMs and GCs: post multi-trade projects and fill crews slot by slot. Free for project managers, always.</p><div class="fld"><label for="pms-n">Your name</label><input id="pms-n" name="name" autocomplete="name"></div><div class="fld"><label for="pms-c">Company</label><input id="pms-c" name="biz" autocomplete="organization"></div><div class="fld"><label for="pms-e">Email</label><input id="pms-e" name="email" type="email" autocomplete="email"></div><div class="fld"><label for="pms-z">Based in</label><select id="pms-z" name="zip">${zipOpts("78704")}</select></div><button class="btn primary block">Create PM account</button></form>`;
 h=h.replace('<div class="card demo">',`<div class="authgrid one">${card}</div><div class="card demo">`);h=h.replace('</div></div></section>',`<button class="demobtn" data-login="m1">${avatar(U("m1"))}<span><b>Copperline Build</b><small>Project manager</small></span></button></div></div></section>`);return h};
 const oa=AFTER.signup;AFTER.signup=(p,q)=>{oa(p,q);const f=document.getElementById("pmsf");if(!f)return;f.onsubmit=e=>{e.preventDefault();const o=readForm(f);act(A.signupPM(o),()=>{if(q.next)location.hash="#"+q.next;else go("dash")})};document.querySelectorAll("[data-login=m1]").forEach(b=>b.onclick=()=>act(A.login("m1"),()=>{if(q.next)location.hash="#"+q.next;else go("dash")}))}}
{const ov=VIEWS.pricing;VIEWS.pricing=(p,q)=>ov(p,q).replace(/<\/section>\s*$/,`<div class="card pmprice"><span class="pmp-i">${I("users",26)}</span><div><h2 class="h-sub">Project managers & GCs</h2><p>Post unlimited multi-trade projects, review applicants, run crew chat and leave crew reviews, all on the <b>same $20/mo plan</b> ($199/yr). No per-project or per-hire fees. Founding members get 3 months free.</p></div><a class="btn primary" href="${href("signup")}">Start as a PM</a></div></section>`)}
{const rv=reviewItem;reviewItem=function(r,c){let h=rv(r,c);if(r.proj){const p=PJ(r.proj),ro=p&&p.roles.find(x=>x.id===r.role);h=h.replace("</header>",`</header><div class="muted small">Crew: ${esc(ro?ro.label:"")} · ${esc(p?p.title:"Project")}</div>`).replace("Verified job","Verified crew")}return h}}
{const od=window.onData;window.onData=()=>{if(ROUTE.v==="project"){const ae=document.activeElement,id=ae&&ae.id,v=ae&&ae.value,to=document.getElementById("pmTo");const tv=to&&to.value;render();if(tv){const t=document.getElementById("pmTo");if(t)t.value=tv}if(id){const e=document.getElementById(id);if(e){e.value=v;e.focus()}}}else if(od)od()}}

function projArt(t,label){const id="pa"+hash(label||t);const sky=`<defs><linearGradient id="${id}s" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#bfe0f2"/><stop offset="1" stop-color="#f7e9d7"/></linearGradient><linearGradient id="${id}w" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stop-color="#5fd0e6"/><stop offset="1" stop-color="#1c8fb8"/></linearGradient></defs><rect width="320" height="140" fill="url(#${id}s)"/>`;
 const pines=(y,c,n,s0)=>Array.from({length:n},(_,i)=>{const x=(i*37+s0)%330-5,h=18+((i*13+s0)%16);return`<path d="M${x} ${y} l${h*.3} -${h} ${h*.3} ${h}z" fill="${c}"/>`}).join("");
 let g="";
 if(t==="pool")g=`<circle cx="262" cy="34" r="14" fill="#E8C98A" opacity=".9"/><path d="M0 80V62l30-6h40l14 10 40-4 20-14h46l18 12 50-2 30 10 32-4v16z" fill="#e2a77a" opacity=".75"/><path d="M0 80l60-8 70 4 80-10 110 8v6z" fill="#cf8a5c" opacity=".7"/><g fill="#4f8a5a"><rect x="28" y="50" width="6" height="32" rx="3"/><path d="M28 64h-6a3 3 0 0 1-3-3v-8" stroke="#4f8a5a" stroke-width="5" fill="none" stroke-linecap="round"/><path d="M34 60h5a3 3 0 0 0 3-3v-6" stroke="#4f8a5a" stroke-width="5" fill="none" stroke-linecap="round"/></g><g><path d="M300 82q-2-26 2-44" stroke="#8a6a44" stroke-width="4" fill="none"/><path d="M302 38q-16-2-22 8M302 38q14-6 22 2M302 38q-8-12-20-10M302 38q10-12 20-8" stroke="#3f7d55" stroke-width="5" fill="none" stroke-linecap="round"/></g><g><path d="M46 84q-1-18 1-30" stroke="#8a6a44" stroke-width="3" fill="none"/><path d="M47 54q-11-1-15 6M47 54q10-4 15 1M47 54q-5-8-13-7" stroke="#3f7d55" stroke-width="4" fill="none" stroke-linecap="round"/></g><rect y="80" width="320" height="60" fill="#d9c7a3"/><path d="M0 80h320v6H0z" fill="#c4ae86"/><rect x="70" y="92" width="150" height="36" rx="10" fill="#efe7da"/><rect x="78" y="98" width="134" height="24" rx="7" fill="url(#${id}w)"/><path d="M90 108q8-4 16 0t16 0M140 112q8-4 16 0t16 0M110 117q8-4 16 0" stroke="#fff" stroke-opacity=".6" fill="none" stroke-width="1.5"/><path d="M232 112l18-20 26 0 6 12-50 8z" fill="#8a6a44"/><g class="pa-ex"><rect x="244" y="104" width="40" height="14" rx="3" fill="#f2b33d"/><rect x="262" y="92" width="18" height="14" rx="2" fill="#f2b33d"/><rect x="266" y="95" width="10" height="7" fill="#bfe0f2"/><path d="M252 104l-14-18-12 6" stroke="#e09a22" stroke-width="5" fill="none" stroke-linecap="round"/><path d="M226 92l-6 8 8 2z" fill="#555"/><rect x="242" y="118" width="44" height="7" rx="3.5" fill="#333"/></g>`;
 else if(t==="barn")g=`<circle cx="60" cy="30" r="13" fill="#E8C98A" opacity=".9"/>${pines(86,"#7da58d",11,9)}<rect y="88" width="320" height="52" fill="#a7c47f"/><path d="M0 104q160-14 320 0v36H0z" fill="#8db36a"/><path d="M110 112V70l55-26 55 26v42z" fill="#b5413a"/><path d="M104 72l61-31 61 31" fill="none" stroke="#5b6670" stroke-width="7" stroke-linejoin="round"/>${Array.from({length:9},(_,i)=>`<path d="M${118+i*11} ${68-((i<5?i:8-i)*5)}V112" stroke="#9c3530" stroke-width="1"/>`).join("")}<rect x="146" y="80" width="38" height="32" fill="#e8e1d5"/><path d="M146 80l38 32M184 80l-38 32" stroke="#b5413a" stroke-width="3"/><rect x="232" y="100" width="40" height="14" rx="3" fill="#2f5d8a"/><rect x="254" y="92" width="18" height="10" rx="2" fill="#2f5d8a"/><circle cx="242" cy="116" r="5" fill="#222"/><circle cx="264" cy="116" r="5" fill="#222"/>`;
 else if(t==="kitchen")g=`<rect width="320" height="140" fill="#f1ebe1"/><rect x="120" y="14" width="80" height="50" rx="3" fill="#bfe0f2"/><path d="M120 50q40-12 80 0v14h-80z" fill="#5c9fb8"/><path d="M160 14v50M120 39h80" stroke="#fff" stroke-width="3"/>${[0,1,2,3].map(i=>`<rect x="${i<2?16+i*50:214+(i-2)*50}" y="16" width="44" height="40" rx="3" fill="#2f4a3a"/><circle cx="${(i<2?16+i*50:214+(i-2)*50)+38}" cy="40" r="1.8" fill="#d9b26a"/>`).join("")}<rect x="0" y="80" width="320" height="8" fill="#e4dccd"/><rect x="0" y="88" width="320" height="52" fill="#2f4a3a"/><rect x="70" y="96" width="180" height="10" rx="2" fill="#f5f2ec"/><rect x="78" y="106" width="164" height="34" fill="#3d5c4a"/>${[110,160,210].map(x=>`<path d="M${x} 0v28" stroke="#333" stroke-width="1"/><path d="M${x-9} 38q9-14 18 0z" fill="#d9b26a"/><circle cx="${x}" cy="40" r="3" fill="#fff3c4" class="pa-glow"/>`).join("")}`;
 else g=`<rect width="320" height="140" fill="#24496b"/>${Array.from({length:16},(_,i)=>`<path d="M${i*20} 0v140" stroke="#fff" stroke-opacity=".08"/>`).join("")}${Array.from({length:7},(_,i)=>`<path d="M0 ${i*20}h320" stroke="#fff" stroke-opacity=".08"/>`).join("")}<path d="M100 110V64l60-34 60 34v46z" fill="none" stroke="#fff" stroke-width="2.5" stroke-dasharray="6 4"/><rect x="146" y="80" width="28" height="30" fill="none" stroke="#fff" stroke-width="2"/><path d="M90 122h140" stroke="#E8C98A" stroke-width="2"/><text x="160" y="134" fill="#E8C98A" font-size="9" text-anchor="middle" font-family="monospace">SITE PLAN</text>`;
 return`<svg viewBox="0 0 320 140" class="art parts" role="img" aria-label="${esc((label||t)+" (illustration)")}" preserveAspectRatio="xMidYMid slice">${t==="kitchen"||t==="custom"||!PTPL[t]?"":sky}${g}</svg>`}

