Object.assign(IP,{arrow:'<path d="M5 12h14M13 6l6 6-6 6"/>',cmd:'<path d="M9 6a3 3 0 1 0-3 3h12a3 3 0 1 0-3-3v12a3 3 0 1 0 3-3H6a3 3 0 1 0 3 3z"/>',bolt:'<path d="M13 2 4 14h7l-1 8 9-12h-7z"/>'});
const US=[[48.4,-124.7],[46.3,-124],[43,-124.5],[40.4,-124.4],[38,-123],[36.6,-121.9],[34.5,-120.6],[34,-118.5],[32.5,-117.1],[32.7,-114.7],[31.3,-111],[31.3,-108.2],[31.8,-106.5],[29.7,-104.5],[29,-103.2],[29.8,-101.4],[27.5,-99.5],[25.9,-97.2],[27.8,-97.4],[29.5,-94.8],[29.7,-93.8],[29.3,-90.5],[29,-89.2],[30.3,-88],[30.4,-86.5],[29.7,-85],[30,-84],[28.9,-82.7],[27,-82.4],[25.2,-81.1],[25.3,-80.4],[26.8,-80],[29,-80.9],[30.7,-81.4],[32,-80.8],[33.8,-78.5],[34.7,-76.5],[35.3,-75.5],[36.9,-76],[37.9,-75.4],[39.3,-74.4],[40.5,-74],[41,-72],[41.5,-71],[41.7,-70],[42.6,-70.7],[43.6,-70.2],[44.4,-68.5],[44.8,-67],[47.3,-68.3],[47,-69.2],[45.3,-70.8],[45,-71.5],[45,-74.7],[44,-76.4],[43.6,-79],[42.9,-78.9],[42,-80.5],[41.7,-83.4],[43,-82.4],[45,-83.3],[46,-84],[46.5,-84.6],[46.8,-87],[47.4,-88],[46.9,-90.5],[46.7,-92.1],[47.8,-89.6],[48,-89.5],[48.6,-93],[49,-95.2],[49,-123]];
const UPROJ=(lat,lon)=>[(lon+96)*Math.cos(lat*Math.PI/180),-lat];
function usBox(pins){let b=[-20,-49.6,20.8,-24.4];if(pins&&pins.length){const P=pins.map(p=>ZIPS[p.zip]).filter(Boolean).map(z=>UPROJ(z[1],z[2]));if(P.length){let x0=Math.min(...P.map(p=>p[0])),x1=Math.max(...P.map(p=>p[0])),y0=Math.min(...P.map(p=>p[1])),y1=Math.max(...P.map(p=>p[1]));if(x1-x0<9&&y1-y0<7){const cx=(x0+x1)/2,cy=(y0+y1)/2,w=Math.max(x1-x0+.7,1.3),h=Math.max(y1-y0+.5,.95);b=[cx-w/2,cy-h/2,cx+w/2,cy+h/2]}}}return b}
function usXY(lat,lon,W,H,b){const[x,y]=UPROJ(lat,lon);const s=Math.min(W/(b[2]-b[0]),H/(b[3]-b[1]));const ox=(W-(b[2]-b[0])*s)/2,oy=(H-(b[3]-b[1])*s)/2;return[ox+(x-b[0])*s,oy+(y-b[1])*s]}
function usPath(W,H,b){return"M"+US.map(([a,c])=>usXY(a,c,W,H,b).map(n=>n.toFixed(1)).join(",")).join("L")+"Z"}
mapSVG=function(W,H,pins,opt){opt=opt||{};const b=opt.full?usBox():usBox(pins);const zoom=(b[2]-b[0])<15;
 const lm=usXY(43.9,-87,W,H,b),s=Math.min(W/(b[2]-b[0]),H/(b[3]-b[1]));
 const grid=Array.from({length:12},(_,i)=>`<path class="m-road" d="M0 ${(H/12*i).toFixed(0)}H${W}"/>`).join("");
 const towns=(()=>{/* v13: town labels never overlap: nearest-to-centre towns are labelled first, each tries 4 spots, the rest keep just their dot */
  const placed=[],seen=new Set(),pts=Object.entries(ZIPS).map(([z,[n,a,c]])=>{const[x,y]=usXY(a,c,W,H,b);return{n:n.split(",")[0],x,y}}).filter(t=>!(t.x<-20||t.y<-20||t.x>W+20||t.y>H+20)).sort((p,q)=>Math.hypot(p.x-W/2,p.y-H/2)-Math.hypot(q.x-W/2,q.y-H/2));
  const lab=t=>{if(!zoom||seen.has(t.n))return"";const w=t.n.length*7.6+4;for(const[dx,dy,end]of[[6,-6,0],[-6,-6,1],[6,15,0],[-6,15,1],[16,4,0],[-16,4,1],[0,-18,2],[0,28,2]]){const tx=t.x+dx,ty=t.y+dy,x0=end===1?tx-w:end===2?tx-w/2:tx,bx=[x0,ty-12,x0+w,ty+3];
   if(bx[0]<2||bx[2]>W-2||bx[1]<2||bx[3]>H-2)continue;if(placed.some(p=>bx[0]<p[2]&&bx[2]>p[0]&&bx[1]<p[3]&&bx[3]>p[1]))continue;placed.push(bx);seen.add(t.n);return`<text x="${tx.toFixed(1)}" y="${ty.toFixed(1)}"${end===1?' text-anchor="end"':end===2?' text-anchor="middle"':""}>${esc(t.n)}</text>`}return""};
  pts.forEach(t=>placed.push([t.x-3.5,t.y-3.5,t.x+3.5,t.y+3.5]));
  pins.forEach(p=>{const z=ZIPS[p.zip];if(z){const[x,y]=usXY(z[1],z[2],W,H,b);placed.push([x-12,y-12,x+12,y+12])}});
  return pts.map(t=>`<g class="m-town"><circle cx="${t.x.toFixed(1)}" cy="${t.y.toFixed(1)}" r="${zoom?3:1.8}"/>${lab(t)}</g>`).join("")})();
 const ps=pins.map(p=>{const z=ZIPS[p.zip];if(!z)return"";const sp=zoom?.06:.25,j=(hash(p.id)%13-6)/6*sp,k=(hash(p.id+"k")%13-6)/6*sp;const[x,y]=usXY(z[1]+j,z[2]+k,W,H,b);return`<g class="m-pin ${p.cls||""}" data-id="${p.id}" transform="translate(${x.toFixed(1)} ${y.toFixed(1)})" tabindex="0" role="button" aria-label="${esc(p.label)}"><title>${esc(p.label)}</title>${opt.pin?opt.pin(p):`<circle r="9"/><text y="3.5" text-anchor="middle">${esc(p.txt||"")}</text>`}</g>`}).join("");
 return`<svg viewBox="0 0 ${W} ${H}" ${opt.fit?`preserveAspectRatio="${opt.fit}"`:""} class="mapsvg usmap" role="img" aria-label="Map of the United States with ${pins.length} locations"><rect width="${W}" height="${H}" class="m-water"/>${zoom?grid:""}<path d="${usPath(W,H,b)}" class="m-land us-land"/><ellipse cx="${lm[0].toFixed(1)}" cy="${lm[1].toFixed(1)}" rx="${(s*.9).toFixed(1)}" ry="${(s*2.2).toFixed(1)}" class="m-water"/>${towns}${ps}</svg>`};
/* decorative national map: dotted land + glowing metros (illustrative demo) */
function usDots(W,H,o){o=o||{};const b=usBox(),step=o.step||14,path=usPath(W,H,b);let dots="";
 const poly=US.map(([a,c])=>usXY(a,c,W,H,b));const inside=(x,y)=>{let c=false;for(let i=0,j=poly.length-1;i<poly.length;j=i++){const[xi,yi]=poly[i],[xj,yj]=poly[j];if((yi>y)!==(yj>y)&&x<(xj-xi)*(y-yi)/(yj-yi)+xi)c=!c}return c};
 for(let y=step/2;y<H;y+=step)for(let x=step/2;x<W;x+=step)if(inside(x,y))dots+=`<circle cx="${x}" cy="${y}" r="${o.r||1.6}"/>`;
 const cnt={};PROS().forEach(u=>cnt[u.zip]=(cnt[u.zip]||0)+1);
 const metros=Object.entries(ZIPS).map(([z,[n,a,c]],i)=>{const[x,y]=usXY(a,c,W,H,b);const k=cnt[z]||0;return`<g class="metro ${k?"has":""}" style="--d:${(i%9)*.35}s" transform="translate(${x.toFixed(1)} ${y.toFixed(1)})"><circle class="mt-pulse" r="${k?10:6}"/><circle class="mt-dot" r="${k?4:2.6}"/>${o.labels&&k?`<text x="8" y="-8">${esc(n.split(",")[0])}</text>`:""}</g>`}).join("");
 return`<svg viewBox="0 0 ${W} ${H}" class="usdots" role="img" aria-label="Illustrative map of demo pros across US metros"><g class="ud-dots">${dots}</g><path d="${path}" class="ud-out"/>${o.arcs?usArcs(W,H,b):""}${metros}</svg>`}
function usArcs(W,H,b){const pairs=[["78704","85254"],["78704","60614"],["85004","80205"],["30307","28202"],["43215","60614"],["98103","97214"],["37203","30307"],["84101","80205"]];return pairs.map(([a,c],i)=>{const A1=ZIPS[a],B1=ZIPS[c];const[x1,y1]=usXY(A1[1],A1[2],W,H,b),[x2,y2]=usXY(B1[1],B1[2],W,H,b);const mx=(x1+x2)/2,my=Math.min(y1,y2)-Math.hypot(x2-x1,y2-y1)*.3;return`<path class="ud-arc" style="--d:${i*.5}s" d="M${x1.toFixed(1)} ${y1.toFixed(1)}Q${mx.toFixed(1)} ${my.toFixed(1)} ${x2.toFixed(1)} ${y2.toFixed(1)}"/>`}).join("")}
const metroCount=()=>new Set(PROS().map(u=>ZIPS[u.zip]&&ZIPS[u.zip][0])).size;
const stateCount=()=>new Set(PROS().map(u=>ZIPS[u.zip]&&ZIPS[u.zip][0].slice(-2))).size;
