function natAcct(m,un){if(!m)return"";return`<div class="acct"><button class="acctbtn" id="acctBtn" aria-haspopup="true" aria-expanded="false">${avatar(m,"sm")}<span class="hide-s">${esc(nameOf(m).split(" ")[0])}</span>${I("chev",14,"rot")}</button><div class="acctmenu" id="acctMenu" hidden><div class="who"><b>${esc(nameOf(m))}</b><small>${m.role==="contractor"?"Pro account":m.role==="pm"?"Project manager":"Customer account"}</small></div><a href="${href("dash")}">${I("grid",16)}Dashboard${un?` <span class="dot">${un}</span>`:""}</a>${m.role==="customer"?`<a href="${href("post")}">${I("plus",16)}Post a job</a><a href="${href("saved")}">${I("heart",16)}Saved pros</a>`:m.role==="pm"?`<a href="${href("newproject")}">${I("plus",16)}Post a project</a><a href="${href("projects")}">${I("users",16)}All projects</a>`:`<a href="${href("pro",m.id)}">${I("user",16)}My profile</a><a href="${href("jobs")}">${I("brief",16)}Job board</a><a href="${href("projects",null,{trade:m.trade,open:"1"})}">${I("users",16)}Crew openings</a>`}<a href="${href("msgs")}">${I("chat",16)}Messages</a><button id="logoutBtn">${I("out",16)}Sign out</button></div></div>`}
function natBind(){const $=id=>document.getElementById(id);$("themeBtn")&&($("themeBtn").onclick=()=>{A.theme();SHELL()});$("menuBtn")&&($("menuBtn").onclick=()=>{menuOpen=!menuOpen;SHELL()});
 if($("acctBtn")){$("acctBtn").onclick=e=>{e.stopPropagation();const mm=$("acctMenu");mm.hidden=!mm.hidden;$("acctBtn").setAttribute("aria-expanded",!mm.hidden)};$("logoutBtn").onclick=()=>{act(A.logout());go("home")}}
 $("resetBtn")&&($("resetBtn").onclick=()=>{A.reset();toast("Demo data reset");go("home")})}
const natOn=(v,k)=>v===k||(k==="projects"&&(v==="project"||v==="newproject"))||(k==="find"&&(v==="pro"||v==="map"))||(k==="jobs"&&v==="job");
const RM=()=>matchMedia("(prefers-reduced-motion:reduce)").matches;
let nio;{const or=render;render=function(){or.apply(this,arguments);if(nio)nio.disconnect();const els=document.querySelectorAll(".reveal,.progrid>*,.projgrid>*");if(!("IntersectionObserver"in window)||RM()){els.forEach(e=>e.classList.add("in"));return}
 nio=new IntersectionObserver(es=>es.forEach(e=>{if(e.isIntersecting){e.target.classList.add("in");nio.unobserve(e.target);e.target.querySelectorAll("[data-count]").forEach(countUp)}}),{rootMargin:"0px 0px -6% 0px"});els.forEach((e,i)=>{e.classList.add("rv");e.style.setProperty("--rd",(i%4)*70+"ms");nio.observe(e)});document.querySelectorAll(".hero [data-count]").forEach(countUp)}}
function countUp(el){if(el.dataset.done)return;el.dataset.done=1;const to=+el.dataset.count,pre=el.dataset.pre||"",suf=el.dataset.suf||"";if(RM()){el.textContent=pre+to+suf;return}const t0=performance.now(),D=1100;const f=t=>{const k=Math.min(1,(t-t0)/D),e=1-Math.pow(1-k,3);el.textContent=pre+Math.round(to*e)+suf;if(k<1)requestAnimationFrame(f)};requestAnimationFrame(f)}
document.addEventListener("pointerdown",e=>{const b=e.target.closest(".btn");if(!b||b.disabled)return;const r=b.getBoundingClientRect(),s=document.createElement("span");s.className="ripple";const d=Math.max(r.width,r.height);s.style.cssText=`width:${d}px;height:${d}px;left:${e.clientX-r.left-d/2}px;top:${e.clientY-r.top-d/2}px`;b.appendChild(s);setTimeout(()=>s.remove(),600)});
document.addEventListener("pointermove",e=>{const c=e.target.closest&&e.target.closest(".spot");if(!c)return;const r=c.getBoundingClientRect();c.style.setProperty("--mx",(e.clientX-r.left)+"px");c.style.setProperty("--my",(e.clientY-r.top)+"px")});
