 for(const k in th){let wait=null;th[k].slice().sort((x,y)=>x.date-y.date).forEach(m=>{if(m.from!==cid){if(wait===null)wait=m.date}else if(wait!==null){if(!/auto-reply, demo/.test(m.text))s.push(m.date-wait);wait=null}})}
