/* =====================================================================
   SAWYER v3: fairness & trust layer (built from the competitor research)
   + easy sign-in UI (codes, magic links, passkeys, OAuth).
   Runs in the browser AND server-side (vm); DOM work stays in AFTER/handlers.
   ===================================================================== */
const LEAD_CAP=3;
function openModal(h,after){modal(h.replace("<h2>","<h2 id=\"mtitle\">"));if(after)after()}
const V3_ACTIONS=["flagLead","reportNoShow","disputeReview","sharePhone","cancelPlan","resumePlan","requestCOI","sendCOI","addLocation","addRecurring","updateMe"];
V2_ACTIONS.push(...V3_ACTIONS);

const engaged=j=>{const s=new Set(j.interested||[]);DB.quotes.filter(q=>q.job===j.id&&q.status!=="declined").forEach(q=>s.add(q.cid));if(j.hired)s.add(j.hired);return s};
const leadSlots=j=>({n:Math.min(engaged(j).size,LEAD_CAP),cap:LEAD_CAP});
const fmtMY=t=>new Date(t).toLocaleDateString("en-US",{month:"short",year:"numeric"});
function credInfo(u){const now=Date.now();const one=(exp,label)=>exp?{label,exp,expired:exp<now,soon:exp>=now&&exp-now<45*DAY}:null;return{lic:one(u.licExp,"License"),ins:one(u.insExp,"Insurance")}}
function reliability(u){const hired=DB.jobs.filter(j=>j.hired===u.id);const ns=hired.filter(j=>j.noShow===u.id).length;const rs=typeof respStats==="function"?respStats(u.id):{n:0};
 let s=100-ns*25-(rs.n&&rs.med>24*36e5?10:0);s=Math.max(0,Math.min(100,s));return{score:s,noShows:ns,jobs:hired.length}}
