function tErr(form,field,msg){form.querySelectorAll(".ferr").forEach(e=>e.remove());form.querySelectorAll("[aria-invalid]").forEach(e=>e.removeAttribute("aria-invalid"));if(!field)return;const el=form.querySelector(`[name="${field}"]`)||form.querySelector(`[data-field="${field}"]`);if(!el){toast(msg,"err");return}
 const box=el.closest(".fld,fieldset")||el.parentNode;el.setAttribute("aria-invalid","true");const p=document.createElement("p");p.className="ferr";p.id="err-"+field;p.setAttribute("role","alert");p.textContent=msg;box.appendChild(p);el.setAttribute("aria-describedby",p.id);(el.focus&&el.tagName!=="FIELDSET")?el.focus():el.querySelector("input")&&el.querySelector("input").focus();box.scrollIntoView({block:"center",behavior:"smooth"})}
