VIEWS.newtravel=()=>{const m=me();const head=UH(I("truck",14)+" Travel work","Post a traveler call","Tell travelers the rate, per diem, hours and license up front. Good calls fill in days.");
 if(!m||!canPostT(m))return`<section class="v2page">${head}<div class="wrap narrow">${empty("truck",m?"Contractor accounts post traveler calls":"Sign in to post traveler work",m?"Posting traveler calls is included in the $20/mo Pro plan. Travelers list for free.":"Electrical contractors and project managers can post calls. Included in the $20/mo Pro plan, no lead fees.",`<div class="row wrapr" style="justify-content:center"><a class="btn primary" href="${href(m?"join":"signup",null,m?null:{next:"/newtravel"})}">${m?"Join as a pro":"Sign in"}</a><a class="btn" href="${href("travel")}">Browse traveler calls</a></div>`)}</div></section>`;
 const tom=new Date(Date.now()+14*864e5).toISOString().slice(0,10);
 return`<section class="v2page">${head}<div class="wrap t5form-w"><form class="card form t5form" id="tpf" novalidate>
 <fieldset><legend>The job</legend>${tF("tp-title","Title",{ph:"Data center journeymen, 6x10s",attrs:'maxlength="90" required'})}<div class="t5row">${tF("tp-loc","City",{ph:"Ashburn",attrs:'required autocomplete="address-level2"'})}${tF("tp-state","State",{select:[["","Pick a state"],...T_STATES]})}${tF("tp-type","Project type",{select:[["","Pick a type"],...T_TYPES]})}</div>
 ${tF("tp-desc","What the work is",{area:1,opt:1,ph:"Scope, site rules, badging, parking, what a typical week looks like…"})}</fieldset>
 <fieldset><legend>Schedule & pay</legend><div class="t5row">${tF("tp-start","Start date",{type:"date",v:tom,attrs:"required"})}${tF("tp-weeks","Duration (weeks)",{type:"number",ph:"12",attrs:'min="1" max="104" inputmode="numeric" required'})}${tF("tp-need","Headcount",{type:"number",ph:"10",attrs:'min="1" max="500" inputmode="numeric" required'})}</div>
 <div class="t5row">${tF("tp-hours","Hours per week",{ph:"50-60 or 6x10s",attrs:"required",hint:"Shown exactly as you type it."})}${tF("tp-rate","Hourly rate ($)",{type:"number",ph:"44",attrs:'min="10" max="250" step="0.5" inputmode="decimal" required'})}${tF("tp-perDiem","Per diem ($/day)",{type:"number",ph:"110",attrs:'min="0" max="400" inputmode="decimal"',hint:"Use 0 if none."})}</div><p class="t5est small" id="tpEst" aria-live="polite"></p></fieldset>
 <fieldset><legend>Requirements</legend><div class="t5row">${tF("tp-lic","License required",{select:[["","Pick one"],...TRADES_T.Electrical.lic]})}${tF("tp-lstate","License state",{select:[["","Any / not required"],...T_STATES],opt:1})}${tF("tp-union","Union",{select:T_UNION,v:"Open shop"})}</div>
 <div class="t5row">${tF("tp-local","IBEW local",{opt:1,ph:"IBEW Local 520"})}${tF("tp-recip","Reciprocity",{opt:1,ph:"Accepts TX, OK, NC journeyman cards"})}</div>${tF("tp-tools","Tools required",{opt:1,ph:"Hand tools per company list, own meter"})}</fieldset>
 <input type="hidden" name="trade" value="Electrical"><div class="actions"><a class="btn ghost" href="${href("travel")}">Cancel</a><button class="btn primary lg" id="tpGo">${I("send",18)}Post traveler call</button></div><p class="small muted">Included in your plan. No per-applicant or per-hire fees.</p></form></div></section>`};
