const tHrs=s=>{s=String(s||"");let m=s.match(/(\d+)\s*x\s*(\d+)/i);if(m)return Math.min(100,+m[1]*+m[2]);m=s.match(/(\d+)\s*hrs?/i);if(m)return Math.min(100,+m[1]);const n=(s.match(/\d+/g)||[]).map(Number).filter(x=>x>0&&x<=100);return n.length>1?Math.round((n[0]+n[1])/2):n[0]||50};
