 saveCall(id){const m=me();if(!m)return{ok:false,need:"login",msg:"Sign in to save calls"};if(!TC(id))return{ok:false,msg:"That call is gone"};m.tsaved=m.tsaved||[];const i=m.tsaved.indexOf(id);if(i>=0)m.tsaved.splice(i,1);else m.tsaved.unshift(id);m.tsaved=m.tsaved.slice(0,100);save();return{ok:true,msg:i>=0?"Removed from saved":"Saved. Find it in your traveler dashboard.",saved:i<0}},
