{const od=A.decideTravel;A.decideTravel=function(id,who,yes){const c=TC(id),a=c&&c.apps.find(x=>x.uid===who&&x.status==="short");if(a)a.status="pending";return od.call(this,id,who,yes)}}
{const op=A.postTravel;A.postTravel=function(o){const r=op.call(this,o);if(r&&r.ok){const c=TC(r.id);let n=0;if(c)DB.users.forEach(u=>{if(u.id===c.by||!u.talerts)return;if(u.talerts.some(a=>(!a.state||a.state===c.state)&&(!a.type||a.type===c.type)&&c.rate>=(a.minRate||0))){n++;notify(u.id,`New traveler call matches your alert: ${c.title} (${c.loc}, ${c.state}, ${tMoney(c.rate)}/hr)`,"tcall:"+c.id)}});if(n)save()}return r}}
