const V8ROLES=[["home","home","Homeowner","Find a pro, compare quotes, track the visit, pay the invoice."],["business","office","Business owner","Recurring service across locations, one place for invoices and COIs."],["pm","layers","Property or project manager","Run multi-trade projects, approve phases, keep vendors in line."],["local","wrench","Contractor","Win jobs with no lead fees, then schedule, invoice and get paid."],["travel","truck","Traveling tradesperson","Honest traveler calls, per diem math, lodging and your dispatch packet."]];
function v8Picker(m,inline){const f=m&&m.focus8;const allowed=k=>!m?true:v7Pro(m)?["local","travel","both"].includes(k)||k==="local"||k==="travel":["home","business","pm"].includes(k)&&(k!=="pm"||m.role==="pm");
 return`<section class="${inline?"o7-wrap ":""}pk8" aria-labelledby="pk8h"><div class="card pk8-c"><h2 id="pk8h">${inline?"Welcome to Sawyer. What brings you here?":"What brings you to Sawyer?"}</h2><p class="muted">We'll set up your home screen around it. You can change this any time in your account.</p>
 <div class="pk8-g" role="radiogroup" aria-label="Your role">${V8ROLES.filter(([k])=>allowed(k)).map(([k,ic,t,s])=>`<button type="button" role="radio" aria-checked="${f===k}" class="pk8-o ${f===k?"on":""}" data-f="${k}"><span class="o7k-i">${I(ic,20)}</span><b>${t}</b><small>${s}</small></button>`).join("")}</div></div></section>`}
function v8BindPicker(){document.querySelectorAll(".pk8-o").forEach(b=>b.onclick=()=>{const m=me();if(!m){go("signup",null,{role:{home:"customer",business:"business",pm:"pm",local:"pro",travel:"pro"}[b.dataset.f]});return}act(A.setFocus(b.dataset.f),()=>go("dash"))})}
VIEWS.welcome=()=>{const m=me();return`<section class="v7page"><div class="o7-wrap" style="max-width:980px">${v8Picker(m,false)}
 <div class="v7cards3">${[["search","Find and hire","Compare up to 3 quotes. Reviews only come from finished jobs."],["route","Track the visit","Get a heads-up when your pro is on the way, with a live ETA."],["card","Pay and review","Pay the invoice by card or bank in one tap, then rate the work."]].map(([i,t,s])=>`<div class="card"><h3>${I(i,18)}${t}</h3><p class="muted">${s}</p></div>`).join("")}</div>
 <div class="v7cards3">${[["office","Run the business","Estimates, invoices, customers, timesheets and COIs. Included in $20/mo."],["cal","Schedule the crew","A week view by person. One tap tells the customer you're on the way."],["truck","Travel smart","Honest call details, per diem math, lodging and a ready-to-send packet."]].map(([i,t,s])=>`<div class="card"><h3>${I(i,18)}${t}</h3><p class="muted">${s}</p></div>`).join("")}</div></div></section>`};
